import { OlapMaterializedView } from "@514labs/moose-lib";

export interface TopProducts {
  product_id: string;
  views: number;
  carts: number;
  purchases: number;
  revenue: number;
}

export const TopProductsView = new OlapMaterializedView<TopProducts>(
  "top_products",
  {
    query: `
      SELECT
        product_id,
        countIf(event_type = 'view') as views,
        countIf(event_type = 'cart') as carts,
        countIf(event_type = 'purchase') as purchases,
        sumIf(toFloat64OrZero(JSONExtractFloat(properties, 'price')), event_type = 'purchase') as revenue
      FROM ProductEvent
      GROUP BY product_id
      ORDER BY revenue DESC, purchases DESC
    `,
    refresh: "incremental"
  }
);

