import { Api } from "@514labs/moose-lib";
import { HourlyActivityView } from "../views/HourlyActivity";

// Define query parameters
export interface HourlyActivityParams {
  start_hour?: string; // Format: YYYY-MM-DD HH:mm:ss
  end_hour?: string;   // Format: YYYY-MM-DD HH:mm:ss
  event_type?: string; // Filter by specific event type
  limit?: number;
}

// Define response interface (matches the view structure)
export interface HourlyActivityResponse {
  hour: string;
  event_type: string;
  event_count: number;
  unique_users: number;
  unique_products: number;
}

// Create the API endpoint
export const hourlyActivityApi = new Api<HourlyActivityParams, HourlyActivityResponse[]>(
  "hourly-activity",
  async ({ start_hour, end_hour, event_type, limit = 24 }, { client, sql }) => {
    // Access the target table from the materialized view
    const targetTable = HourlyActivityView.targetTable;

    let whereConditions = [];
    if (start_hour) {
      whereConditions.push(`hour >= '${start_hour}'`);
    }
    if (end_hour) {
      whereConditions.push(`hour <= '${end_hour}'`);
    }
    if (event_type) {
      whereConditions.push(`event_type = '${event_type}'`);
    }

    const whereClause = whereConditions.length > 0 ? `WHERE ${whereConditions.join(' AND ')}` : '';

    const query = sql.statement`
      SELECT
        toString(hour) as hour,
        event_type,
        sum(event_count) as event_count,
        sum(unique_users) as unique_users,
        sum(unique_products) as unique_products
      FROM ${targetTable}
      ${sql.raw(whereClause)}
      GROUP BY hour, event_type
      ORDER BY hour DESC, event_type
      LIMIT ${limit}
    `;

    const result = await client.query.execute<HourlyActivityResponse>(query);
    return result.json();
  }
);

