const fs = require('fs');
const path = require('path');

// Base URL for the ingest endpoint
const INGEST_URL = 'http://localhost:4000/ingest/ProductEvent';

// Function to load and send all seed events
async function loadSeedData() {
  const eventsDir = '/data/events';
  const files = fs.readdirSync(eventsDir).filter(f => f.endsWith('.json'));

  console.log(`Loading ${files.length} events...`);

  let successCount = 0;
  let errorCount = 0;

  for (const file of files.sort()) {
    try {
      const filePath = path.join(eventsDir, file);
      const eventData = JSON.parse(fs.readFileSync(filePath, 'utf8'));

      console.log(`Sending event: ${eventData.event_id}`);

      const response = await fetch(INGEST_URL, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(eventData)
      });

      if (response.ok) {
        console.log(`✅ Successfully sent: ${eventData.event_id}`);
        successCount++;
      } else {
        console.error(`❌ Failed to send ${eventData.event_id}: ${response.status} ${response.statusText}`);
        const errorBody = await response.text();
        console.error(`Error body: ${errorBody}`);
        errorCount++;
      }

      // Small delay to avoid overwhelming the server
      await new Promise(resolve => setTimeout(resolve, 100));

    } catch (error) {
      console.error(`❌ Error processing ${file}:`, error.message);
      errorCount++;
    }
  }

  console.log(`\nSummary:`);
  console.log(`✅ Successful: ${successCount}`);
  console.log(`❌ Failed: ${errorCount}`);
  console.log(`📊 Total: ${successCount + errorCount}`);
}

// Function to test API endpoints
async function testApiEndpoints() {
  const endpoints = [
    'http://localhost:4000/api/query/top-products',
    'http://localhost:4000/api/query/conversion-funnel',
    'http://localhost:4000/api/query/hourly-activity'
  ];

  console.log('\nTesting API endpoints...');

  for (const endpoint of endpoints) {
    try {
      const start = Date.now();
      const response = await fetch(endpoint);
      const elapsed = Date.now() - start;

      if (response.ok) {
        const data = await response.json();
        console.log(`✅ ${endpoint}: ${response.status} (${elapsed}ms) - ${data.length} records`);
      } else {
        console.log(`❌ ${endpoint}: ${response.status} ${response.statusText}`);
      }
    } catch (error) {
      console.error(`❌ ${endpoint}: ${error.message}`);
    }
  }
}

// Main execution
async function main() {
  console.log('🚀 Starting Analytics Pipeline Test');

  // Wait a bit for the server to be ready
  console.log('⏳ Waiting for server to be ready...');
  await new Promise(resolve => setTimeout(resolve, 5000));

  // Check if server is responding
  try {
    const response = await fetch('http://localhost:4000/health');
    if (!response.ok) {
      throw new Error(`Server not ready: ${response.status}`);
    }
    console.log('✅ Server is ready!');
  } catch (error) {
    console.error('❌ Server not ready:', error.message);
    console.log('Attempting to load data anyway...');
  }

  // Load seed data
  await loadSeedData();

  // Wait for data to propagate through the pipeline
  console.log('\n⏳ Waiting for data to propagate...');
  await new Promise(resolve => setTimeout(resolve, 3000));

  // Test API endpoints
  await testApiEndpoints();

  console.log('\n🎉 Analytics Pipeline test complete!');
}

// Handle errors and run main function
main().catch(error => {
  console.error('❌ Fatal error:', error);
  process.exit(1);
});

