  unique_users_purchased: number;
  total_views: number;
  total_carts: number;
  total_purchases: number;
  view_to_cart_rate: number;
  cart_to_purchase_rate: number;
  overall_conversion_rate: number;
}

export const ConversionFunnelView = new OlapMaterializedView<ConversionFunnel>(
  "conversion_funnel",
  {
    query: `
      WITH funnel_stats AS (
        SELECT
          product_id,
          uniqIf(user_id, event_type = 'view') as unique_users_viewed,
          uniqIf(user_id, event_type = 'cart') as unique_users_carted,
          uniqIf(user_id, event_type = 'purchase') as unique_users_purchased,
          countIf(event_type = 'view') as total_views,
          countIf(event_type = 'cart') as total_carts,
          countIf(event_type = 'purchase') as total_purchases
        FROM ProductEvent
        GROUP BY product_id
      )
      SELECT
        product_id,
        unique_users_viewed,
        unique_users_carted,
        unique_users_purchased,
        total_views,
        total_carts,
        total_purchases,
        CASE WHEN unique_users_viewed > 0
          THEN round(unique_users_carted / unique_users_viewed * 100, 2)
          ELSE 0
        END as view_to_cart_rate,
        CASE WHEN unique_users_carted > 0
          THEN round(unique_users_purchased / unique_users_carted * 100, 2)
          ELSE 0
        END as cart_to_purchase_rate,
        CASE WHEN unique_users_viewed > 0
          THEN round(unique_users_purchased / unique_users_viewed * 100, 2)
          ELSE 0
        END as overall_conversion_rate
      FROM funnel_stats
      ORDER BY unique_users_viewed DESC
    `,
    refresh: "incremental"
  }
