import { Api } from "@514labs/moose-lib";
import { TopProductsView } from "../views/TopProducts";

// Define query parameters for filtering and pagination
export interface TopProductsParams {
  limit?: number;
}

// Define response interface (matches the view structure)
export interface TopProductsResponse {
  product_id: string;
  views: number;
  carts: number;
  purchases: number;
  revenue: number;
}

// Create the API endpoint
export const topProductsApi = new Api<TopProductsParams, TopProductsResponse[]>(
  "top-products",
  async ({ limit = 10 }, { client, sql }) => {
    // Access the target table from the materialized view
    const targetTable = TopProductsView.targetTable;

    const query = sql.statement`
      SELECT
        product_id,
        sum(views) as views,
        sum(carts) as carts,
        sum(purchases) as purchases,
        sum(revenue) as revenue
      FROM ${targetTable}
      GROUP BY product_id
      ORDER BY revenue DESC, purchases DESC
      LIMIT ${limit}
    `;

    const result = await client.query.execute<TopProductsResponse>(query);
    return result.json();
  }
);

