import { Api } from "@514labs/moose-lib";
import { ConversionFunnelView } from "../views/ConversionFunnel";

// Define query parameters
export interface ConversionFunnelParams {
  product_id?: string;
  limit?: number;
}

// Define response interface (matches the view structure)
export interface ConversionFunnelResponse {
  product_id: string;
  unique_users_viewed: number;
  unique_users_carted: number;
  unique_users_purchased: number;
  total_views: number;
  total_carts: number;
  total_purchases: number;
  view_to_cart_rate: number;
  cart_to_purchase_rate: number;
  overall_conversion_rate: number;
}

// Create the API endpoint
export const conversionFunnelApi = new Api<ConversionFunnelParams, ConversionFunnelResponse[]>(
  "conversion-funnel",
  async ({ product_id, limit = 10 }, { client, sql }) => {
    // Access the target table from the materialized view
    const targetTable = ConversionFunnelView.targetTable;

    let query;
    if (product_id) {
      // Filter by specific product
      query = sql.statement`
        SELECT
          product_id,
          sum(unique_users_viewed) as unique_users_viewed,
          sum(unique_users_carted) as unique_users_carted,
          sum(unique_users_purchased) as unique_users_purchased,
          sum(total_views) as total_views,
          sum(total_carts) as total_carts,
          sum(total_purchases) as total_purchases,
          view_to_cart_rate,
          cart_to_purchase_rate,
          overall_conversion_rate
        FROM ${targetTable}
        WHERE product_id = ${product_id}
        GROUP BY product_id, view_to_cart_rate, cart_to_purchase_rate, overall_conversion_rate
        ORDER BY unique_users_viewed DESC
        LIMIT ${limit}
      `;
    } else {
      // Return all products
      query = sql.statement`
        SELECT
          product_id,
          sum(unique_users_viewed) as unique_users_viewed,
          sum(unique_users_carted) as unique_users_carted,
          sum(unique_users_purchased) as unique_users_purchased,
