import { MaterializedView, sql } from "@514labs/moose-lib";
import { ProductEventPipeline } from "../ingest/ProductEvent";

export interface TopProducts {
  product_id: string;
  views: number;
  carts: number;
  purchases: number;
  revenue: number;
}

const sourceTable = ProductEventPipeline.table!;

export const TopProductsView = new MaterializedView<TopProducts>({
  materializedViewName: "top_products",
  selectTables: [sourceTable],
  selectStatement: sql.statement`
    SELECT
      product_id,
      countIf(event_type = 'view') as views,
      countIf(event_type = 'cart') as carts,
      countIf(event_type = 'purchase') as purchases,
      sumIf(toFloat64OrZero(JSONExtractFloat(properties, 'price')), event_type = 'purchase') as revenue
    FROM ${sourceTable}
    GROUP BY product_id
    ORDER BY revenue DESC, purchases DESC
  `,
  targetTable: {
    name: "top_products",
    orderByFields: ["revenue"]
  }
});

import { MaterializedView, sql } from "@514labs/moose-lib";
import { ProductEventPipeline } from "../ingest/ProductEvent";

export interface ConversionFunnel {
  product_id: string;
  unique_users_viewed: number;
  unique_users_carted: number;
  unique_users_purchased: number;
  total_views: number;
  total_carts: number;
  total_purchases: number;
  view_to_cart_rate: number;
  cart_to_purchase_rate: number;
  overall_conversion_rate: number;
}

const sourceTable = ProductEventPipeline.table!;

export const ConversionFunnelView = new MaterializedView<ConversionFunnel>({
  materializedViewName: "conversion_funnel",
  selectTables: [sourceTable],
  selectStatement: sql.statement`
    WITH funnel_stats AS (
      SELECT
        product_id,
        uniqIf(user_id, event_type = 'view') as unique_users_viewed,
        uniqIf(user_id, event_type = 'cart') as unique_users_carted,
        uniqIf(user_id, event_type = 'purchase') as unique_users_purchased,
        countIf(event_type = 'view') as total_views,
        countIf(event_type = 'cart') as total_carts,
        countIf(event_type = 'purchase') as total_purchases
      FROM ${sourceTable}
      GROUP BY product_id
    )
    SELECT
      product_id,
      unique_users_viewed,
      unique_users_carted,
      unique_users_purchased,
      total_views,
      total_carts,
      total_purchases,
      CASE WHEN unique_users_viewed > 0
        THEN round(unique_users_carted / unique_users_viewed * 100, 2)
        ELSE 0
      END as view_to_cart_rate,
      CASE WHEN unique_users_carted > 0
        THEN round(unique_users_purchased / unique_users_carted * 100, 2)
        ELSE 0
      END as cart_to_purchase_rate,
      CASE WHEN unique_users_viewed > 0
        THEN round(unique_users_purchased / unique_users_viewed * 100, 2)
        ELSE 0
      END as overall_conversion_rate
    FROM funnel_stats
    ORDER BY unique_users_viewed DESC
  `,
  targetTable: {
    name: "conversion_funnel",
    orderByFields: ["unique_users_viewed"]
  }
});

import { MaterializedView, sql } from "@514labs/moose-lib";
import { ProductEventPipeline } from "../ingest/ProductEvent";

export interface HourlyActivity {
  hour: string;
  event_type: string;
  event_count: number;
  unique_users: number;
  unique_products: number;
}

const sourceTable = ProductEventPipeline.table!;

export const HourlyActivityView = new MaterializedView<HourlyActivity>({
  materializedViewName: "hourly_activity",
  selectTables: [sourceTable],
  selectStatement: sql.statement`
    SELECT
      toStartOfHour(event_ts) as hour,
      event_type,
      count(*) as event_count,
      uniq(user_id) as unique_users,
      uniq(product_id) as unique_products
    FROM ${sourceTable}
    GROUP BY hour, event_type
    ORDER BY hour DESC, event_type
  `,
  targetTable: {
    name: "hourly_activity",
    orderByFields: ["hour", "event_type"]
  }
});

